const AUTH_KEY='berryVibesAccountsV6',SESSION_KEY='berryVibesSessionV6';
const DEFAULT_STATE={logs:[],water:0,fast:null,fastHistory:[],customRecipes:[],restaurantVault:[],builder:[],cart:[],wishlist:[],saved:[],battleMode:'protein',profile:{name:'',height:'',weight:118,reason:'',photo:'',theme:'berry',accent:'#6e46ff'}};
let state=null,foodVisible=18,recipeVisible=18,factVisible=18,currentMove='walk',currentDuration=20,currentRestaurant=0,battleMode='protein',unitChoice='tsp';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2200)}
function hashLite(str){let h=2166136261;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16)}
function accounts(){try{return JSON.parse(localStorage.getItem(AUTH_KEY)||'{}')}catch{return {}}}
function session(){return localStorage.getItem(SESSION_KEY)||''}
function stateKey(){return 'berryVibesStateV6:'+session().toLowerCase()}
function loadState(){try{const raw=JSON.parse(localStorage.getItem(stateKey())||'{}');return {...structuredClone(DEFAULT_STATE),...raw,profile:{...DEFAULT_STATE.profile,...(raw.profile||{})},logs:Array.isArray(raw.logs)?raw.logs:[],customRecipes:Array.isArray(raw.customRecipes)?raw.customRecipes:[],restaurantVault:Array.isArray(raw.restaurantVault)?raw.restaurantVault:[]}}catch{return structuredClone(DEFAULT_STATE)}}
function save(){if(session())localStorage.setItem(stateKey(),JSON.stringify(state))}
function requireAuth(){if(document.body.dataset.page==='login')return true;if(!session()){location.href='login.html';return false}return true}
function signOut(){localStorage.removeItem(SESSION_KEY);location.href='login.html'}
function greeting(){const h=new Date().getHours();return h<12?'GOOD MORNING ☀️':h<17?'GOOD AFTERNOON ✨':h<21?'GOOD EVENING 🌙':'LATE-NIGHT BERRY MODE 🌌'}
function allRecipes(){return [...CCD_RECIPES,...state.customRecipes]}
function baseCalories(r){return Math.round(r?.nutrition?.calories??r?.calories??estimateCalories(r||{}))}
function estimateCalories(r){const t=((r.name||'')+' '+(r.group||'')).toLowerCase();let c=260;if(/drink|coffee|tea|latte/.test(t))c=95;if(/dip|sauce|frosting/.test(t))c=150;if(/cookie|donut|brownie|cake|muffin/.test(t))c=230;if(/sandwich|philly|pizza|burrito|quesadilla|pasta/.test(t))c=430;if(/egg|breakfast/.test(t))c=280;if(/snack|side/.test(t))c=200;return c}
function autoNutrition(r){if(r.nutrition){return {calories:Math.round(r.nutrition.calories??baseCalories(r)),protein:+(r.nutrition.protein??0),carbs:+(r.nutrition.carbs??0),fat:+(r.nutrition.fat??0),fiber:+(r.nutrition.fiber??0),exact:true}}const c=baseCalories(r),t=((r.name||'')+' '+(r.group||'')+' '+(r.ingredients||[]).join(' ')).toLowerCase();let p=.18,carb=.50,f=.32,fiber=Math.max(2,Math.round(c/115));if(/chicken|steak|egg|yogurt|cottage|turkey/.test(t)){p=.28;carb=.39;f=.33}if(/coffee|tea|drink|latte/.test(t)){p=.16;carb=.60;f=.24;fiber=Math.max(1,Math.round(c/120))}if(/brownie|cake|cookie|donut|chocolate/.test(t)){p=.11;carb=.56;f=.33}if(/wrap|burrito|pizza|pasta|sandwich|philly/.test(t)){p=.24;carb=.44;f=.32}return {calories:c,protein:Math.round(c*p/4),carbs:Math.round(c*carb/4),fat:Math.round(c*f/9),fiber,exact:false}}
function recipeImage(r){const t=((r.name||'')+' '+(r.group||'')).toLowerCase();if(/coffee|tea|drink|latte|mocha/.test(t))return imageMap.coffee;if(/donut/.test(t))return imageMap.donut;if(/chocolate|brownie|cake|cookie/.test(t))return imageMap.chocolate;if(/sandwich|philly|bagel|toast/.test(t))return imageMap.sandwich;if(/bowl|salad/.test(t))return imageMap.bowl;if(/savory|pizza|pasta|wrap|burrito|egg|chicken/.test(t))return imageMap.savory;return imageMap.sweet}
function tasteText(r){if(r.taste)return r.taste;const t=(r.name||'').toLowerCase();if(/chocolate|brownie|lava/.test(t))return'RICH, CHOCOLATEY AND COZY — EXPECT A SOFT, DESSERT-STYLE BITE.';if(/cinnamon|pancake|french toast/.test(t))return'WARM, CINNAMONNY AND BREAKFAST-COZY — SOFT, SWEET-LEANING AND COMFORTING.';if(/philly|steak|sandwich|bagel/.test(t))return'SAVORY, TOASTY AND SATISFYING — EXPECT MELTY, JUICY COMFORT-FOOD ENERGY.';if(/coffee|tea|latte/.test(t))return'SMOOTH, AROMATIC AND SIP-ABLE — EXPECT A COZY CAFÉ VIBE.';return'SOFT, COZY AND PLAYFUL — EXPECT A REPEATABLE CCD COMFORT-FOOD MOMENT.'}
function recipeFacts(r){const n=autoNutrition(r);return [`🔥 ${n.calories} KCAL PER SAVED SERVING ${n.exact?'IN THE RECORDED CARD.':'AS AN AUTO CCD ARCHIVE ESTIMATE.'}`,`💪🏽 ${Math.round(n.protein)}G PROTEIN · 🌾 ${Math.round(n.fiber)}G FIBER IN THE CURRENT CARD.`,`😋 ${tasteText(r)}`]}
function scaleNut(n,m=1){return {calories:Math.round(n.calories*m),protein:Math.round(n.protein*m*10)/10,carbs:Math.round(n.carbs*m*10)/10,fat:Math.round(n.fat*m*10)/10,fiber:Math.round(n.fiber*m*10)/10}}
function bar(label,v,max,suffix='G'){const p=Math.max(0,Math.min(100,v/max*100));return `<div class="bar-row"><b>${esc(label)}</b><div class="bar-track"><span class="bar-fill" style="width:${p}%"></span></div><strong>${Math.round(v)}${suffix}</strong></div>`}
function totals(){const food=state.logs.filter(x=>x.type==='food'),moves=state.logs.filter(x=>x.type==='move');const s=food.reduce((a,x)=>{const n=x.nutrition||{};a.calories+=+n.calories||0;a.protein+=+n.protein||0;a.carbs+=+n.carbs||0;a.fat+=+n.fat||0;a.fiber+=+n.fiber||0;return a},{calories:0,protein:0,carbs:0,fat:0,fiber:0});return {...s,burn:moves.reduce((a,x)=>a+(+x.burn||0),0)}}
function addFood(name,n,detail='CCD FOOD'){state.logs.push({type:'food',emoji:'🍽️',name,detail,nutrition:n,at:Date.now()});save();toast('FOOD LOGGED AT '+new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})+' 🍓')}
function applyTheme(){const p=state.profile||DEFAULT_STATE.profile;document.body.classList.remove(...THEMES.map(t=>'theme-'+t[0]));if(p.theme&&p.theme!=='berry')document.body.classList.add('theme-'+p.theme);document.documentElement.style.setProperty('--accent',p.accent||'#6e46ff');const meta=$('meta[name="theme-color"]');if(meta)meta.content=p.accent||'#6e46ff'}
function common(){ $$('[data-greeting]').forEach(x=>x.textContent=greeting()+(state.profile.name?', '+state.profile.name.toUpperCase():''));$$('[data-signout]').forEach(b=>b.addEventListener('click',signOut));const chip=$('[data-profile-chip]');if(chip){chip.innerHTML=`<span>${state.profile.photo?'<img src="'+state.profile.photo+'" alt="">':'🍓'}</span><b>${esc(state.profile.name||'BERRY PROFILE')}</b>`}const glow=$('#cursorGlow');if(glow)document.addEventListener('pointermove',e=>{glow.style.left=e.clientX+'px';glow.style.top=e.clientY+'px'});$$('.tilt-card,.food-card,.recipe-card,.shop-card').forEach(card=>{card.addEventListener('pointermove',e=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(800px) rotateY(${x*3}deg) rotateX(${-y*3}deg) translateY(-2px)`});card.addEventListener('pointerleave',()=>card.style.transform='')});$$('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog')?.close()))}
function renderLog(el,filter=null){if(!el)return;let a=[...state.logs].filter(x=>!filter||filter(x)).reverse().slice(0,18);el.innerHTML=a.length?a.map(x=>`<div class="log-entry"><span>${x.emoji||'✦'}</span><div><b>${esc(x.name)}</b><small>${esc(x.detail||'')} · ${new Date(x.at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</small></div><strong>${x.type==='food'?(x.nutrition?.calories||0)+' KCAL':x.type==='move'?(x.burn||0)+' BURN':'LOGGED'}</strong></div>`).join(''):'<div class="empty">YOUR FIRST LOG WILL POP UP HERE ✦</div>'}

function initLogin(){if(session()){location.href='index.html';return}const si=$('#signInForm'),su=$('#signUpForm'),sit=$('#signInTab'),sut=$('#signUpTab');function mode(signup){sit.classList.toggle('active',!signup);sut.classList.toggle('active',signup);si.hidden=signup;su.hidden=!signup;si.classList.toggle('hidden',signup);su.classList.toggle('hidden',!signup)}sit.onclick=()=>mode(false);sut.onclick=()=>mode(true);su.onsubmit=e=>{e.preventDefault();const email=$('#signUpEmail').value.trim().toLowerCase(),name=$('#signUpName').value.trim(),pass=$('#signUpPassword').value;if(pass.length<6)return toast('USE 6+ CHARACTERS');const a=accounts();if(a[email])return toast('THAT LOCAL PROFILE ALREADY EXISTS');a[email]={name,hash:hashLite(pass)};localStorage.setItem(AUTH_KEY,JSON.stringify(a));localStorage.setItem(SESSION_KEY,email);state=structuredClone(DEFAULT_STATE);state.profile.name=name;save();location.href='index.html'};si.onsubmit=e=>{e.preventDefault();const email=$('#signInEmail').value.trim().toLowerCase(),pass=$('#signInPassword').value,a=accounts();if(!a[email]||a[email].hash!==hashLite(pass))return toast('EMAIL OR PASSWORD DOES NOT MATCH');localStorage.setItem(SESSION_KEY,email);location.href='index.html'}}
function initDashboard(){const t=totals();$('#todayDate').textContent=new Date().toLocaleDateString([],{weekday:'short',month:'short',day:'numeric'}).toUpperCase();$('#todayTime').textContent=new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});$('#dashboardStats').innerHTML=[['🍽️','FOOD',Math.round(t.calories)+' KCAL'],['💪🏽','PROTEIN',Math.round(t.protein)+'G'],['🌾','FIBER',Math.round(t.fiber)+'G'],['💧','WATER',Math.round(state.water)+' OZ'],['🚶🏽‍♀️','MOVE BURN',t.burn+' KCAL']].map(x=>`<div class="stat-card"><span>${x[0]} ${x[1]}</span><strong>${x[2]}</strong></div>`).join('');$('#macroBars').innerHTML=[bar('CARBS',t.carbs,250),bar('PROTEIN',t.protein,100),bar('FAT',t.fat,80),bar('FIBER',t.fiber,30)];const remLo=Math.max(0,2100-t.calories),remHi=Math.max(0,2150-t.calories);$('#maintenanceText').textContent=t.calories?`${Math.round(t.calories)} KCAL LOGGED · ${Math.round(remLo)}–${Math.round(remHi)} KCAL TO THE 2,100–2,150 REFERENCE`:'NO FOOD LOGGED YET · 2,100–2,150 KCAL REFERENCE';$('#maintenanceFill').style.width=Math.min(100,t.calories/2150*100)+'%';const tags={'GRAINS + BASE':0,'PROTEIN':0,'FRUIT + VEG':0,'FUN + EXTRAS':0};state.logs.filter(x=>x.type==='food').forEach(x=>{const s=(x.name||'').toLowerCase();if(/bread|bagel|pancake|oat|flour|rice|pasta|tortilla|pizza|cracker/.test(s))tags['GRAINS + BASE']++;if(/egg|chicken|steak|yogurt|cheese|milk|cottage|protein/.test(s))tags.PROTEIN++;if(/apple|berry|veggie|spinach|pumpkin|orange|avocado/.test(s))tags['FRUIT + VEG']++;if(/chocolate|cookie|cake|donut|dip|sauce|candy|ice cream/.test(s))tags['FUN + EXTRAS']++});const mx=Math.max(1,...Object.values(tags));$('#pyramidBars').innerHTML=Object.entries(tags).map(([k,v])=>bar(k,v,mx,'×')).join('');renderLog($('#recentLogs'));$('#clearToday').onclick=()=>{if(confirm('CLEAR TODAY\'S LOCAL FOOD, MOVEMENT + WATER LOGS?')){state.logs=[];state.water=0;save();initDashboard()}}}
function groupsTo(select,arr){if(!select)return;const g=[...new Set(arr.map(r=>r.group).filter(Boolean))].sort();select.innerHTML='<option value="all">ALL WORLDS</option>'+g.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}
function foodCard(r){const n=autoNutrition(r);return `<article class="food-card"><img src="${recipeImage(r)}" alt="Food photography representing ${esc(r.name)}"><div class="card-body"><span class="mini-kicker">${esc(r.group||'CCD ARCHIVE')}</span><h3>${esc(r.name)}</h3><div class="macro-chips"><span>${n.calories} KCAL</span><span>${Math.round(n.protein)}G P</span><span>${Math.round(n.fiber)}G FIBER</span></div><p>${n.exact?'RECORDED/CALCULATED NUTRITION':'AUTO CCD ARCHIVE ESTIMATE'}</p><button class="primary-button" data-food-open="${esc(r.id)}">LOG / VIEW ✦</button></div></article>`}
function initFoods(){groupsTo($('#foodGroup'),allRecipes());function render(){const q=$('#foodSearch').value.toLowerCase(),g=$('#foodGroup').value;const a=allRecipes().filter(r=>(g==='all'||r.group===g)&&((r.name+' '+r.group).toLowerCase().includes(q)));$('#foodGrid').innerHTML=a.slice(0,foodVisible).map(foodCard).join('');$$('[data-food-open]').forEach(b=>b.onclick=()=>openFood(b.dataset.foodOpen));$('#loadMoreFood').hidden=foodVisible>=a.length}$('#foodSearch').oninput=()=>{foodVisible=18;render()};$('#foodGroup').onchange=()=>{foodVisible=18;render()};$('#loadMoreFood').onclick=()=>{foodVisible+=18;render()};render();$('#sotdGrid').innerHTML=SOTD_ITEMS.map((s,i)=>{const qs=[];for(let q=s.min;q<=s.max+1e-9;q+=s.step)qs.push(q);return `<article class="sotd-card" style="background-image:url('${s.image}')"><span>${s.emoji} ${esc(s.unit)}</span><h3>${esc(s.name)}</h3><p>${esc(s.note)}</p><div class="portion-buttons">${qs.map(q=>`<button data-sotd="${i}" data-sotd-qty="${q}">LOG ${q} · ${Math.round(s.calories*q)} KCAL</button>`).join('')}</div></article>`}).join('');$$('[data-sotd]').forEach(b=>b.onclick=()=>{const s=SOTD_ITEMS[+b.dataset.sotd],qty=+b.dataset.sotdQty,c=s.calories*qty,n={calories:Math.round(c),carbs:Math.round(c*.58/4),protein:Math.max(1,Math.round(c*.07/4)),fat:Math.round(c*.35/9),fiber:Math.max(0,Math.round(c/180))};addFood('SOTD · '+s.name,n,(s.recorded?'RECORDED CALORIE · ':'AUTO CCD ESTIMATE · ')+qty+' '+s.unit+(qty===1?'':'S'))});function water(){ $('#waterTotal').textContent=Math.round(state.water)+' OZ';$('#waterOrb').innerHTML=`<b>${Math.round(state.water)}</b><span>OZ</span>`}$$('[data-water]').forEach(b=>b.onclick=()=>{state.water=Math.round((state.water+(+b.dataset.water))*10)/10;save();water();toast('WATER LOGGED NOW 💧')});water()}
function openFood(id){const r=allRecipes().find(x=>x.id===id);if(!r)return;const n=autoNutrition(r),d=$('#foodDialog');$('#foodDialogBody').innerHTML=`<div class="dialog-inner"><div class="dialog-hero"><img src="${recipeImage(r)}" alt="Food photography representing ${esc(r.name)}"><div><span class="mini-kicker">${esc(r.group)}</span><h2>${esc(r.name)}</h2><div class="macro-chips"><span>${n.calories} KCAL</span><span>${Math.round(n.carbs)}G C</span><span>${Math.round(n.protein)}G P</span><span>${Math.round(n.fat)}G FAT</span><span>${Math.round(n.fiber)}G FIBER</span></div><label class="field">SERVING MULTIPLIER<input id="foodMult" type="range" min=".25" max="3" step=".25" value="1"><output id="foodMultOut">1×</output></label><div class="nutrition-ribbon" id="foodScaled"></div><button class="primary-button wide" id="foodLogNow">LOG AT CURRENT TIME ✦</button></div></div><div class="what-expect"><h3>WHAT TO EXPECT / WHAT IT TASTES LIKE</h3><p>${esc(tasteText(r))}</p></div></div>`;function update(){const m=+$('#foodMult').value,s=scaleNut(n,m);$('#foodMultOut').textContent=m+'×';$('#foodScaled').innerHTML=nutRibbon(s)}$('#foodMult').oninput=update;$('#foodLogNow').onclick=()=>{addFood(r.name,scaleNut(n,+$('#foodMult').value),`${+$('#foodMult').value}× SERVING · ${n.exact?'RECORDED/CALCULATED':'AUTO CCD ESTIMATE'}`);d.close()};update();d.showModal()}
function nutRibbon(n){return [['CAL',n.calories],['CARBS',Math.round(n.carbs)+'G'],['PROTEIN',Math.round(n.protein)+'G'],['FAT',Math.round(n.fat)+'G'],['FIBER',Math.round(n.fiber)+'G']].map(x=>`<div><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join('')}
function recipeCard(r){const n=autoNutrition(r);return `<article class="recipe-card"><img src="${recipeImage(r)}" alt="Food photography representing ${esc(r.name)}"><div class="card-body"><span class="mini-kicker">${esc(r.group)}</span><h3>${esc(r.name)}</h3><p>${n.calories} KCAL · ${n.exact?'RECORDED/CALCULATED':'ARCHIVE ESTIMATE'}</p><button class="primary-button" data-recipe-open="${esc(r.id)}">OPEN RECIPE ✦</button></div></article>`}
function initRecipes(){groupsTo($('#recipeGroup'),allRecipes());PANTRY.forEach(p=>{$('#pantrySelect').insertAdjacentHTML('beforeend',`<option value="${p.id}">${esc(p.name)} · ${p.unit}</option>`);if(['TSP','TBSP','1/4 CUP'].includes(p.unit))$('#unitIngredient').insertAdjacentHTML('beforeend',`<option value="${p.id}">${esc(p.name)}</option>`)});function render(){const q=$('#recipeSearch').value.toLowerCase(),g=$('#recipeGroup').value,a=allRecipes().filter(r=>(g==='all'||r.group===g)&&((r.name+' '+r.group).toLowerCase().includes(q)));$('#recipeGrid').innerHTML=a.slice(0,recipeVisible).map(recipeCard).join('');$$('[data-recipe-open]').forEach(b=>b.onclick=()=>openRecipe(b.dataset.recipeOpen));$('#loadMoreRecipes').hidden=recipeVisible>=a.length}$('#recipeSearch').oninput=()=>{recipeVisible=18;render()};$('#recipeGroup').onchange=()=>{recipeVisible=18;render()};$('#loadMoreRecipes').onclick=()=>{recipeVisible+=18;render()};$('#randomRecipe').onclick=()=>{const a=allRecipes();openRecipe(a[Math.floor(Math.random()*a.length)].id)};render();$('#pantryAmount').oninput=()=>$('#pantryAmountOut').textContent=(+$('#pantryAmount').value)+'×';$('#addIngredient').onclick=()=>{const p=PANTRY.find(x=>x.id===$('#pantrySelect').value);state.builder.push({id:p.id,amount:+$('#pantryAmount').value});save();renderBuilder()};$('#clearBuilder').onclick=()=>{state.builder=[];save();renderBuilder()};$('#saveRecipe').onclick=saveBuilder;$$('#unitSwitch button').forEach(b=>b.onclick=()=>{$$('#unitSwitch button').forEach(x=>x.classList.remove('active'));b.classList.add('active');unitChoice=b.dataset.unit;renderUnit()});$('#unitIngredient').onchange=renderUnit;$('#unitAmount').oninput=renderUnit;renderBuilder();renderUnit()}
function renderBuilder(){const el=$('#builderIngredients');el.innerHTML=state.builder.length?state.builder.map((x,i)=>{const p=PANTRY.find(z=>z.id===x.id);return `<div class="ingredient-row"><div><b>${esc(p.name)}</b><small>${x.amount} × ${esc(p.unit)}</small></div><strong>${Math.round(p.calories*x.amount)} KCAL</strong><button data-remove-ing="${i}">×</button></div>`}).join(''):'<div class="empty">ADD INGREDIENTS FROM THE PANTRY DECK ✦</div>';$$('[data-remove-ing]').forEach(b=>b.onclick=()=>{state.builder.splice(+b.dataset.removeIng,1);save();renderBuilder()});const n=builderTotals();$('#builderNutrition').innerHTML=nutRibbon(n)}
function builderTotals(){return state.builder.reduce((a,x)=>{const p=PANTRY.find(z=>z.id===x.id);if(p){a.calories+=p.calories*x.amount;a.carbs+=p.carbs*x.amount;a.protein+=p.protein*x.amount;a.fat+=p.fat*x.amount;a.fiber+=p.fiber*x.amount}return a},{calories:0,carbs:0,protein:0,fat:0,fiber:0})}
function saveBuilder(){const name=$('#builderName').value.trim();if(!name||!state.builder.length)return toast('ADD A NAME + INGREDIENTS FIRST');const n=builderTotals(),ings=state.builder.map(x=>{const p=PANTRY.find(z=>z.id===x.id);return `${x.amount} × ${p.unit} ${p.name}`});state.customRecipes.push({id:'custom-'+Date.now(),name,group:'MY CCD RECIPE LAB',source:'Created in Berry Vibes Recipe Lab',ingredients:ings,steps:['Built in the interactive Berry Vibes recipe lab. Add your preferred cooking method and notes when you make it.'],nutrition:{...n},calories:Math.round(n.calories),yieldText:'1 saved builder batch',taste:'YOUR CUSTOM CCD CREATION — EXPECT THE FLAVOR AND TEXTURE TO FOLLOW THE INGREDIENTS YOU BUILT INTO THE CARD.'});state.builder=[];save();toast('RECIPE SAVED TO YOUR CCD ARCHIVE 🧪');renderBuilder()}
function openRecipe(id){const r=allRecipes().find(x=>x.id===id);if(!r)return;const n=autoNutrition(r),facts=recipeFacts(r),d=$('#recipeDialog');$('#recipeDialogBody').innerHTML=`<div class="dialog-inner"><div class="dialog-hero"><img src="${recipeImage(r)}" alt="Food photography representing ${esc(r.name)}"><div><span class="mini-kicker">${esc(r.group)}</span><h2>${esc(r.name)}</h2><p>${esc(r.source||'CCD ARCHIVE')}</p><label class="field">SERVING SCALE<input id="recipeScale" type="range" min=".5" max="3" step=".5" value="1"><output id="recipeScaleOut">1×</output></label><div class="nutrition-ribbon" id="recipeScaled"></div></div></div><h3>VERTICAL INGREDIENT CHART</h3><div class="vertical-ingredients">${(r.ingredients?.length?r.ingredients:['ORIGINAL QUANTITIES NOT RECOVERED']).map((x,i)=>`<div><b>${i+1}</b><span>${esc(x)}</span></div>`).join('')}</div><div class="what-expect"><h3>WHAT TO EXPECT / WHAT IT TASTES LIKE</h3><p>${esc(tasteText(r))}</p></div><h3>METHOD</h3><div class="recipe-facts">${(r.steps?.length?r.steps:['METHOD NOT RECOVERED IN THE ARCHIVE CARD.']).map((x,i)=>`<div>${i+1}. ${esc(x)}</div>`).join('')}</div><h3>THREE CCD ONE-LINERS</h3><div class="recipe-facts">${facts.map(x=>`<div>${esc(x)}</div>`).join('')}</div></div>`;function update(){const m=+$('#recipeScale').value;$('#recipeScaleOut').textContent=m+'×';$('#recipeScaled').innerHTML=nutRibbon(scaleNut(n,m))}$('#recipeScale').oninput=update;update();d.showModal()}
function unitFactor(p,u){if(p.unit==='TBSP')return u==='tsp'?1/3:u==='tbsp'?1:16;if(p.unit==='TSP')return u==='tsp'?1:u==='tbsp'?3:48;if(p.unit==='1/4 CUP')return u==='tsp'?1/12:u==='tbsp'?1/4:4;return 1}
function renderUnit(){const p=PANTRY.find(x=>x.id===$('#unitIngredient').value)||PANTRY[0],amt=+($('#unitAmount').value||1),f=unitFactor(p,unitChoice)*amt,n={calories:p.calories*f,carbs:p.carbs*f,protein:p.protein*f,fat:p.fat*f,fiber:p.fiber*f};$('#unitNutrition').innerHTML=nutRibbon(n);$('#unitReference').innerHTML=`<span>🥄 1 TSP ≈ <b>${Math.round(p.calories*unitFactor(p,'tsp')*10)/10} KCAL</b></span><span>🥄 1 TBSP ≈ <b>${Math.round(p.calories*unitFactor(p,'tbsp')*10)/10} KCAL</b></span><span>🥣 1 CUP ≈ <b>${Math.round(p.calories*unitFactor(p,'cup'))} KCAL</b></span>`}
function initMovement(){const g=$('#movementGrid');g.innerHTML=MOVEMENTS.map(m=>`<article class="movement-card ${m.id===currentMove?'active':''}" data-move="${m.id}"><span>${m.emoji}</span><h3>${m.name}</h3><p>${m.copy}</p></article>`).join('');$$('[data-move]').forEach(c=>c.onclick=()=>{currentMove=c.dataset.move;initMovementChoice();$$('[data-move]').forEach(x=>x.classList.toggle('active',x.dataset.move===currentMove))});$('#durationGrid').innerHTML=[10,15,20,30,45,60].map(x=>`<button data-duration="${x}" class="${x===currentDuration?'active':''}">${x} MIN</button>`).join('');$$('[data-duration]').forEach(b=>b.onclick=()=>{currentDuration=+b.dataset.duration;$$('[data-duration]').forEach(x=>x.classList.toggle('active',+x.dataset.duration===currentDuration));initMovementChoice()});$('#logMovement').onclick=()=>{const m=MOVEMENTS.find(x=>x.id===currentMove),burn=movementBurn();state.logs.push({type:'move',emoji:m.emoji,name:m.name,detail:`${currentDuration} MIN · PRESET DURATION · AUTO CLICK TIME`,burn,at:Date.now()});save();toast('MOVEMENT LOGGED NOW '+m.emoji);renderLog($('#movementLog'),x=>x.type==='move')};renderLog($('#movementLog'),x=>x.type==='move');initMovementChoice()}
function movementBurn(){const m=MOVEMENTS.find(x=>x.id===currentMove),lb=+state.profile.weight||118,kg=lb*.453592;return Math.round(m.met*3.5*kg/200*currentDuration)}
function initMovementChoice(){const m=MOVEMENTS.find(x=>x.id===currentMove),burn=movementBurn();$('#moveChoice').textContent=m.name+' · '+currentDuration+' MIN';$('#burnEstimate').textContent=burn+' KCAL';$('#movementFacts').innerHTML=[`${m.emoji} ${m.copy}`,`⏱️ ${currentDuration} MIN IS A BUTTON PRESET — NO DURATION TYPING.`,`✨ ${burn} KCAL IS A MET-STYLE ESTIMATE AND STAYS SEPARATE FROM FOOD CALORIES.`].map(x=>`<div>${x}</div>`).join('')}
function initFasting(){let selected='16:8';$('#fastGrid').innerHTML=FAST_PRESETS.map(f=>`<button data-fast="${f.id}" class="${f.id===selected?'active':''}">${f.id}<span>${f.hours}H FAST</span></button>`).join('');$$('[data-fast]').forEach(b=>b.onclick=()=>{selected=b.dataset.fast;$$('[data-fast]').forEach(x=>x.classList.toggle('active',x.dataset.fast===selected));$('#fastSelected').textContent=selected+' SELECTED'});$('#startFast').onclick=()=>{const f=FAST_PRESETS.find(x=>x.id===selected);state.fast={style:f.id,hours:f.hours,start:Date.now()};save();renderFast();toast('FAST START TIME SAVED NOW ⏳')};$('#breakFast').onclick=()=>{if(!state.fast)return toast('START A FAST FIRST');const done={...state.fast,end:Date.now()};state.fastHistory.push(done);state.fast=null;save();renderFast();toast('FAST BREAK TIME SAVED NOW ✨')};renderFast()}
function renderFast(){const f=state.fast;if(f){const mins=Math.max(0,(Date.now()-f.start)/60000),pct=Math.min(100,mins/(f.hours*60)*100);$('#fastRing').style.setProperty('--fast-progress',pct+'%');$('#fastStatusTitle').textContent=f.style+' · ACTIVE';$('#fastStatusText').textContent=`STARTED ${new Date(f.start).toLocaleString()} · ABOUT ${Math.floor(mins/60)}H ${Math.floor(mins%60)}M ELAPSED.`}else{$('#fastRing').style.setProperty('--fast-progress','0%');$('#fastStatusTitle').textContent='NOT STARTED';$('#fastStatusText').textContent='CHOOSE A PRESET AND TAP START FAST NOW.'}const el=$('#fastHistory');const a=[...state.fastHistory].reverse().slice(0,12);el.innerHTML=a.length?a.map(x=>`<div class="log-entry"><span>⏳</span><div><b>${esc(x.style)} FAST</b><small>${new Date(x.start).toLocaleString()} → ${new Date(x.end).toLocaleString()}</small></div><strong>${((x.end-x.start)/3600000).toFixed(1)}H</strong></div>`).join(''):'<div class="empty">COMPLETED FASTS WILL APPEAR HERE.</div>'}
function initRestaurants(){renderRestaurantTabs();renderPersonalRestaurantVault();$('#lookupRestaurant').onclick=lookupRestaurant;$('#clearRestaurantSearch')?.addEventListener('click',()=>{$('#customRestaurant').value='';$('#customRestaurantItem').value='';$('#lookupResult').innerHTML='THE LOCAL VAULT IS CHECKED FIRST. UNKNOWN ITEMS USE YOUR SECURE NUTRITION ENDPOINT — THE SITE WILL NOT INVENT “EXACT” NUMBERS.'})}
function renderRestaurantTabs(){const t=$('#restaurantTabs');t.innerHTML=RESTAURANT_CHAINS.map((c,i)=>`<button data-chain="${i}" class="${i===currentRestaurant?'active':''}">${esc(c.name)}</button>`).join('');$$('[data-chain]').forEach(b=>b.onclick=()=>{currentRestaurant=+b.dataset.chain;renderRestaurantTabs()});const c=RESTAURANT_CHAINS[currentRestaurant];$('#restaurantItems').innerHTML=c.items.map((i,idx)=>`<article class="restaurant-card"><img src="${c.image}" alt="Restaurant food photography representing ${esc(c.name)}"><div class="card-body"><span class="mini-kicker">${esc(c.name)}</span><h3>${esc(i.name)}</h3><div class="macro-chips"><span>${i.calories} KCAL</span><span>${i.protein}G P</span><span>${i.fiber}G FIBER</span></div><button class="primary-button" data-rest-item="${idx}">LOG / PORTION ✦</button></div></article>`).join('');$$('[data-rest-item]').forEach(b=>b.onclick=()=>openRestaurant(currentRestaurant,+b.dataset.restItem))}
function openRestaurant(ci,ii){const c=RESTAURANT_CHAINS[ci],i=c.items[ii],d=$('#restaurantDialog');$('#restaurantDialogBody').innerHTML=`<div class="dialog-inner"><div class="dialog-hero"><img src="${c.image}" alt="Restaurant food photography"><div><span class="mini-kicker">${esc(c.name)}</span><h2>${esc(i.name)}</h2><p>${esc(c.source||'SAVED RESTAURANT VAULT')}</p><div class="nutrition-ribbon" id="restNut"></div><div class="portion-buttons">${[.25,.5,.75,1,1.25,1.5].map(x=>`<button data-rest-portion="${x}">${x}×</button>`).join('')}</div><button class="primary-button wide" id="logRest">LOG 1× NOW</button></div></div></div>`;let portion=1;function up(){const n=scaleNut(i,portion);$('#restNut').innerHTML=nutRibbon(n);$('#logRest').textContent=`LOG ${portion}× NOW · ${n.calories} KCAL`}$$('[data-rest-portion]').forEach(b=>b.onclick=()=>{portion=+b.dataset.restPortion;up()});$('#logRest').onclick=()=>{addFood(`${c.name} · ${i.name}`,scaleNut(i,portion),`${portion}× SAVED RESTAURANT PORTION`);d.close()};up();d.showModal()}
function normalizeRestaurantText(s){return String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function restaurantVaultId(restaurant,name){return `${normalizeRestaurantText(restaurant)}::${normalizeRestaurantText(name)}`}
function cleanRestaurantNutrition(data,fallbackRestaurant='',fallbackName=''){const n={restaurant:String(data?.restaurant||data?.brand||fallbackRestaurant||'RESTAURANT').trim(),name:String(data?.name||data?.item||data?.food_name||fallbackName||'MENU ITEM').trim(),calories:+data?.calories,carbs:+data?.carbs,protein:+data?.protein,fat:+data?.fat,fiber:+data?.fiber,servingQuantity:data?.servingQuantity??data?.serving_qty??null,servingUnit:data?.servingUnit??data?.serving_unit??'',source:String(data?.source||'CONNECTED NUTRITION ENDPOINT').trim(),verified:data?.verified!==false};if(!['calories','carbs','protein','fat','fiber'].every(k=>Number.isFinite(n[k])))return null;n.id=restaurantVaultId(n.restaurant,n.name);return n}
function findBuiltInRestaurant(restaurant,item){const rn=normalizeRestaurantText(restaurant),it=normalizeRestaurantText(item);for(const c of RESTAURANT_CHAINS){const cn=normalizeRestaurantText(c.name);if(cn.includes(rn)||rn.includes(cn)){const found=c.items.find(x=>{const xn=normalizeRestaurantText(x.name);return xn.includes(it)||it.includes(xn)});if(found)return {restaurant:c.name,name:found.name,calories:+found.calories,carbs:+found.carbs,protein:+found.protein,fat:+found.fat,fiber:+found.fiber,source:c.source||'BUILT-IN RESTAURANT VAULT',verified:found.verified!==false,builtIn:true,image:c.image}}}return null}
function findPersonalRestaurant(restaurant,item){const rn=normalizeRestaurantText(restaurant),it=normalizeRestaurantText(item);return state.restaurantVault.find(x=>{const r=normalizeRestaurantText(x.restaurant),n=normalizeRestaurantText(x.name);return (r.includes(rn)||rn.includes(r))&&(n.includes(it)||it.includes(n))})||null}
function saveRestaurantToVault(data){const clean=cleanRestaurantNutrition(data);if(!clean)return toast('COULD NOT SAVE THAT NUTRITION RESULT');const idx=state.restaurantVault.findIndex(x=>x.id===clean.id);const saved={...clean,savedAt:Date.now()};if(idx>=0)state.restaurantVault[idx]=saved;else state.restaurantVault.unshift(saved);save();renderPersonalRestaurantVault();toast(idx>=0?'SAVED FOOD UPDATED 💖':'SAVED TO MY RESTAURANT VAULT 💖')}
function removeRestaurantFromVault(id){state.restaurantVault=state.restaurantVault.filter(x=>x.id!==id);save();renderPersonalRestaurantVault();toast('REMOVED FROM MY RESTAURANT VAULT')}
function renderPersonalRestaurantVault(){const box=$('#personalRestaurantVault');if(!box)return;const items=state.restaurantVault;box.innerHTML=items.length?items.map(x=>`<article class="personal-vault-card"><div class="personal-vault-emoji">🍔</div><div><span class="mini-kicker">${esc(x.restaurant)}</span><h3>${esc(x.name)}</h3><div class="macro-chips"><span>${Math.round(x.calories)} KCAL</span><span>${Math.round(x.protein)}G P</span><span>${Math.round(x.fiber)}G FIBER</span></div><small>${esc(x.source||'SAVED LOOKUP')}</small></div><div class="personal-vault-actions"><button class="primary-button" data-vault-log="${esc(x.id)}">LOG NOW</button><button class="ghost-button" data-vault-delete="${esc(x.id)}">REMOVE</button></div></article>`).join(''):'<div class="empty">NO CUSTOM RESTAURANT FOODS SAVED YET. SEARCH A NEW ITEM, THEN TAP “SAVE TO MY VAULT.” ✨</div>';$$('[data-vault-log]').forEach(b=>b.onclick=()=>{const x=state.restaurantVault.find(v=>v.id===b.dataset.vaultLog);if(x)addFood(`${x.restaurant} · ${x.name}`,x,'MY SAVED RESTAURANT VAULT')});$$('[data-vault-delete]').forEach(b=>b.onclick=()=>removeRestaurantFromVault(b.dataset.vaultDelete))}
function lookupSourceBadge(data){if(data.builtIn)return'✅ BUILT-IN VERIFIED VAULT';if(data.personal)return'💖 MY SAVED RESTAURANT VAULT';return data.verified?'🌐 CONNECTED NUTRITION RESULT':'⚠️ CONNECTED NUTRITION ESTIMATE'}
function renderRestaurantLookup(data,{canSave=false,personal=false}={}){const clean=cleanRestaurantNutrition(data,data.restaurant,data.name);if(!clean)return;clean.personal=personal;const serving=[clean.servingQuantity,clean.servingUnit].filter(Boolean).join(' ');$('#lookupResult').innerHTML=`<div class="lookup-card"><div class="lookup-title"><div><span class="mini-kicker">${lookupSourceBadge({...data,personal})}</span><h3>${esc(clean.restaurant)} · ${esc(clean.name)}</h3><p>${serving?`SERVING: ${esc(serving)} · `:''}${esc(clean.source)}</p></div><span class="lookup-check">${data.builtIn?'🏪':personal?'💖':'✨'}</span></div><div class="nutrition-ribbon">${nutRibbon(clean)}</div><div class="lookup-actions"><button class="primary-button" id="logLookup">LOG NOW · ${Math.round(clean.calories)} KCAL</button>${canSave?'<button class="ghost-button" id="saveLookup">💖 SAVE TO MY VAULT</button>':''}</div></div>`;$('#logLookup').onclick=()=>addFood(`${clean.restaurant} · ${clean.name}`,clean,personal?'MY SAVED RESTAURANT VAULT':data.builtIn?'BUILT-IN RESTAURANT VAULT':'CONNECTED NUTRITION LOOKUP');if(canSave)$('#saveLookup').onclick=()=>saveRestaurantToVault(clean)}
async function lookupRestaurant(){const rn=$('#customRestaurant').value.trim(),item=$('#customRestaurantItem').value.trim();if(!rn||!item)return toast('ENTER A RESTAURANT + MENU ITEM');const built=findBuiltInRestaurant(rn,item);if(built){renderRestaurantLookup(built);return}const mine=findPersonalRestaurant(rn,item);if(mine){renderRestaurantLookup({...mine,personal:true},{personal:true});return}const endpoint=String(window.BERRY_RESTAURANT_ENDPOINT||'').trim();if(!endpoint){$('#lookupResult').innerHTML='⚠️ NOT IN THE BUILT-IN OR PERSONAL VAULT YET. ADD YOUR CLOUDFLARE WORKER URL IN <code>config.js</code> TO TURN ON AUTOMATIC VERIFIED LOOKUPS.';return}$('#lookupResult').innerHTML='<div class="lookup-loading">✨ CHECKING YOUR SECURE NUTRITION ENDPOINT…</div>';try{const u=new URL(endpoint,location.href);u.searchParams.set('restaurant',rn);u.searchParams.set('item',item);const r=await fetch(u,{headers:{Accept:'application/json'}});let payload={};try{payload=await r.json()}catch{}if(!r.ok)throw new Error(payload?.message||`LOOKUP FAILED (${r.status})`);const clean=cleanRestaurantNutrition(payload,rn,item);if(!clean)throw new Error('THE ENDPOINT RESPONSE DID NOT INCLUDE ALL REQUIRED NUTRITION FIELDS');renderRestaurantLookup(clean,{canSave:true})}catch(e){$('#lookupResult').innerHTML=`<div class="lookup-error">⚠️ ${esc(e.message||'THE VERIFIED ENDPOINT DID NOT RETURN USABLE NUTRITION.')}<br><small>YOUR BUILT-IN + PERSONAL VAULTS ARE STILL WORKING. NOTHING WAS INVENTED.</small></div>`}}
function initBattle(){const o=allRecipes().map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');$('#battleA').innerHTML=o;$('#battleB').innerHTML=o;$('#battleB').selectedIndex=Math.min(10,$('#battleB').options.length-1);$$('[data-battle-mode]').forEach(b=>b.onclick=()=>{battleMode=b.dataset.battleMode;$$('[data-battle-mode]').forEach(x=>x.classList.toggle('active',x.dataset.battleMode===battleMode));battlePreview()});$('#battleA').onchange=battlePreview;$('#battleB').onchange=battlePreview;$('#battleLaunch').onclick=()=>{battlePreview(true);toast('BATTLE COMPLETE 🏆')};battlePreview()}
function battleValue(n){if(battleMode==='protein')return n.protein;if(battleMode==='fiber')return n.fiber;if(battleMode==='calories')return -n.calories;return (n.protein+n.fiber)/Math.max(1,n.calories)*100}
function initBattleBars(a,b,na,nb){const maxC=Math.max(na.calories,nb.calories,1),maxP=Math.max(na.protein,nb.protein,1),maxF=Math.max(na.fiber,nb.fiber,1);$('#battleBars').innerHTML=`${bar(a.name+' · CAL',na.calories,maxC,'')} ${bar(b.name+' · CAL',nb.calories,maxC,'')} ${bar(a.name+' · PROTEIN',na.protein,maxP,'G')} ${bar(b.name+' · PROTEIN',nb.protein,maxP,'G')} ${bar(a.name+' · FIBER',na.fiber,maxF,'G')} ${bar(b.name+' · FIBER',nb.fiber,maxF,'G')}`}
function battlePreview(animate=false){const a=allRecipes().find(r=>r.id===$('#battleA').value),b=allRecipes().find(r=>r.id===$('#battleB').value);if(!a||!b)return;const na=autoNutrition(a),nb=autoNutrition(b),va=battleValue(na),vb=battleValue(nb),win=va===vb?null:va>vb?a:b;const rule={protein:'HIGHER PROTEIN',fiber:'HIGHER FIBER',calories:'LOWER CALORIES',density:'HIGHER (PROTEIN + FIBER) PER 100 KCAL'}[battleMode];$('#battleArena').innerHTML=`<article class="fighter"><img src="${recipeImage(a)}" alt="${esc(a.name)}"><h3>${esc(a.name)}</h3><p>${na.calories} KCAL · ${Math.round(na.protein)}G P · ${Math.round(na.fiber)}G FIBER</p></article><div class="winner-badge"><strong>${win?'🏆':'🤝'}</strong><span>${win?esc(win.name)+' WINS':'TIE'}<br>RULE: ${rule}</span></div><article class="fighter"><img src="${recipeImage(b)}" alt="${esc(b.name)}"><h3>${esc(b.name)}</h3><p>${nb.calories} KCAL · ${Math.round(nb.protein)}G P · ${Math.round(nb.fiber)}G FIBER</p></article>`;initBattleBars(a,b,na,nb)}
function initShop(){const cats=[...new Set(SHOP_PRODUCTS.map(p=>p.category))].sort();$('#shopCategory').innerHTML='<option value="all">ALL DESIGN WORLDS</option>'+cats.map(c=>`<option>${esc(c)}</option>`).join('');$('#shopSearch').oninput=renderShop;$('#shopCategory').onchange=renderShop;$('#shopSort').onchange=renderShop;$('#openCart').onclick=openCart;$('#showWishlist').onclick=()=>{ $('#shopSearch').value='';renderShop('wishlist')};$('#showSaved').onclick=()=>{$('#shopSearch').value='';renderShop('saved')};renderShop()}
function renderShop(mode='all'){const q=$('#shopSearch').value.toLowerCase(),c=$('#shopCategory').value,sort=$('#shopSort').value;let a=SHOP_PRODUCTS.filter(p=>(c==='all'||p.category===c)&&((p.name+' '+p.category).toLowerCase().includes(q)));if(mode==='wishlist')a=a.filter(p=>state.wishlist.includes(p.id));if(mode==='saved')a=a.filter(p=>state.saved.includes(p.id));if(sort==='price-low')a.sort((x,y)=>x.price-y.price);if(sort==='price-high')a.sort((x,y)=>y.price-x.price);if(sort==='name')a.sort((x,y)=>x.name.localeCompare(y.name));$('#shopGrid').innerHTML=a.map(p=>`<article class="shop-card"><img src="${p.image}" alt="${esc(p.name)} design work"><div class="card-body"><span class="mini-kicker">${esc(p.category)}</span><h3>${esc(p.name)}</h3><p>${esc(p.desc||'Berry Vibes Studio design work.')}</p><div class="price-row"><strong>$${p.price.toFixed(2)}</strong><span>DIGITAL / CONCEPT</span></div><div class="shop-actions"><button data-cart="${p.id}">ADD TO CART</button><button data-wish="${p.id}" title="Wishlist">${state.wishlist.includes(p.id)?'♥':'♡'}</button><button data-save="${p.id}" title="Save">${state.saved.includes(p.id)?'🔖':'📑'}</button></div></div></article>`).join('')||'<div class="empty">NO DESIGN ITEMS MATCH THIS VIEW.</div>';$$('[data-cart]').forEach(b=>b.onclick=()=>{state.cart.push(b.dataset.cart);save();shopCounts();toast('ADDED TO CART 🛍️')});$$('[data-wish]').forEach(b=>b.onclick=()=>{toggleList(state.wishlist,b.dataset.wish);save();renderShop(mode);shopCounts()});$$('[data-save]').forEach(b=>b.onclick=()=>{toggleList(state.saved,b.dataset.save);save();renderShop(mode);shopCounts()});shopCounts()}
function toggleList(a,id){const i=a.indexOf(id);i>=0?a.splice(i,1):a.push(id)}
function shopCounts(){$('#cartCount').textContent=state.cart.length;$('#wishlistCount').textContent=state.wishlist.length;$('#savedCount').textContent=state.saved.length}
function openCart(){const d=$('#cartDialog'),items=state.cart.map(id=>SHOP_PRODUCTS.find(p=>p.id===id)).filter(Boolean),total=items.reduce((a,p)=>a+p.price,0);$('#cartDialogBody').innerHTML=`<div class="dialog-inner"><span class="mini-kicker">BERRY CART</span><h2>YOUR CART</h2><div class="cart-list">${items.length?items.map((p,i)=>`<div class="cart-item"><img src="${p.image}" alt=""><div><b>${esc(p.name)}</b><small>$${p.price.toFixed(2)}</small></div><button class="ghost-button" data-remove-cart="${i}">REMOVE</button></div>`).join(''):'<div class="empty">YOUR CART IS EMPTY.</div>'}</div><div class="cart-total"><b>TOTAL</b><strong>$${total.toFixed(2)}</strong></div><button class="primary-button wide" id="checkoutPreview" ${items.length?'':'disabled'}>PROCEED TO CHECKOUT PREVIEW ✦</button><p class="auth-note">DEMO CHECKOUT: STATIC GITHUB PAGES CANNOT SAFELY PROCESS CARD PAYMENTS BY ITSELF. CONNECT STRIPE CHECKOUT, SHOPIFY, PAYPAL, OR ANOTHER HOSTED PAYMENT FLOW FOR REAL SALES.</p></div>`;$$('[data-remove-cart]').forEach(b=>b.onclick=()=>{state.cart.splice(+b.dataset.removeCart,1);save();openCart();shopCounts()});const co=$('#checkoutPreview');if(co)co.onclick=()=>toast('CHECKOUT PREVIEW READY — CONNECT A HOSTED PAYMENT FLOW FOR REAL CHARGES.');d.showModal()}
function initFacts(){groupsTo($('#factGroup'),allRecipes());function render(){const q=$('#factSearch').value.toLowerCase(),g=$('#factGroup').value,a=allRecipes().filter(r=>(g==='all'||r.group===g)&&((r.name+' '+r.group).toLowerCase().includes(q)));$('#factGrid').innerHTML=a.slice(0,factVisible).map(r=>`<article class="fact-card"><span class="mini-kicker">${esc(r.group)}</span><h3>${esc(r.name)}</h3>${recipeFacts(r).map(x=>`<div class="fact-stack"><div>${esc(x)}</div></div>`).join('')}</article>`).join('');$('#loadMoreFacts').hidden=factVisible>=a.length}$('#factSearch').oninput=()=>{factVisible=18;render()};$('#factGroup').onchange=()=>{factVisible=18;render()};$('#loadMoreFacts').onclick=()=>{factVisible+=18;render()};render();$('#exerciseFacts').innerHTML=MOVEMENTS.map(m=>`<article class="movement-card"><span>${m.emoji}</span><h3>${m.name}</h3><p>${m.copy}</p><p>⏱️ PRESET DURATION BUTTONS · NO TYPING.</p><p>✨ AUTO CLICK-TIME LOGGING.</p></article>`).join('')}
function initProfile(){const p=state.profile;$('#profileName').value=p.name||'';$('#profileHeight').value=p.height||'';$('#profileWeight').value=p.weight||'';$('#profileReason').value=p.reason||'';$('#accentColor').value=p.accent||'#6e46ff';function photo(){const el=$('#profilePreview');if(p.photo){el.style.backgroundImage=`url(${p.photo})`;el.textContent=''}else{el.style.backgroundImage='';el.textContent='🍓'}$('#profileMini').textContent=(p.name||'BERRY PROFILE').toUpperCase()}photo();$('#profilePic').onchange=e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>2_500_000)return toast('USE AN IMAGE UNDER 2.5 MB FOR LOCAL STORAGE');const r=new FileReader();r.onload=()=>{p.photo=r.result;save();photo();toast('PROFILE PIC SAVED ✦')};r.readAsDataURL(f)};$('#profileForm').onsubmit=e=>{e.preventDefault();p.name=$('#profileName').value.trim();p.height=$('#profileHeight').value.trim();p.weight=+$('#profileWeight').value||118;p.reason=$('#profileReason').value.trim();save();toast('PROFILE SAVED 👤')};$('#themeGrid').innerHTML=THEMES.map(t=>`<button class="theme-choice ${p.theme===t[0]?'active':''}" data-theme="${t[0]}" style="background:linear-gradient(135deg,${t[1]},${t[2]})"><b>${t[0].toUpperCase()}</b></button>`).join('');$$('[data-theme]').forEach(b=>b.onclick=()=>{p.theme=b.dataset.theme;save();applyTheme();$$('[data-theme]').forEach(x=>x.classList.toggle('active',x.dataset.theme===p.theme))});$('#accentColor').oninput=e=>{p.accent=e.target.value;save();applyTheme()};$('#resetTheme').onclick=()=>{p.theme='berry';p.accent='#6e46ff';$('#accentColor').value=p.accent;save();applyTheme();initProfile()}}

function init(){if(document.body.dataset.page==='login'){initLogin();return}if(!requireAuth())return;state=loadState();applyTheme();common();const p=document.body.dataset.page;({index:initDashboard,foods:initFoods,recipes:initRecipes,movement:initMovement,fasting:initFasting,restaurants:initRestaurants,battle:initBattle,shop:initShop,facts:initFacts,profile:initProfile}[p]||(()=>{}))()}
document.addEventListener('DOMContentLoaded',init);
